python3 << 'EOF'
# Try pypdf or similar
try:
    import pypdf
    reader = pypdf.PdfReader('/tmp/PA3.pdf')
    for i, page in enumerate(reader.pages):
        print(f"=== PAGE {i+1} ===")
        print(page.extract_text())
except ImportError:
    pass

try:
    import PyPDF2
    with open('/tmp/PA3.pdf', 'rb') as f:
        reader = PyPDF2.PdfReader(f)
        for i, page in enumerate(reader.pages):
            print(f"=== PAGE {i+1} ===")
            print(page.extract_text())
except ImportError:
    print("No PDF library available")
EOF

